export const getPromptOneLiner = (title, description) => {
  const t = title.toLowerCase();
  if (t.includes('instagram caption') || t === 'caption generator') {
    return "Hook-driven captions tuned for your brand voice.";
  }
  if (t.includes('elevator pitch')) {
    return "A concise pitch you can record or read aloud.";
  }
  if (t.includes('cold email') || t.includes('outreach')) {
    return "Personalized B2B outreach and first-touch emails that get replies.";
  }
  if (t.includes('meta ad') || t.includes('facebook ad')) {
    return "Generate highly optimized ad copy combinations to A/B test.";
  }
  if (t.includes('whatsapp broadcast')) {
    return "Short, urgent messages optimized for high open rates.";
  }
  if (t.includes('linkedin thought')) {
    return "Long-form professional posts that drive saves and comments.";
  }
  if (t.includes('newsletter section') || t.includes('newsletter')) {
    return "Conversational openers that earn the next scroll.";
  }
  if (t.includes('print headline') || t.includes('banner copy') || t.includes('poster copy')) {
    return "Punchy lines tuned for billboard, poster, and outdoor campaigns.";
  }
  
  // Dynamic fallbacks based on common categories/titles
  if (t.includes('calendar')) return "Plan and organize your content schedule systematically.";
  if (t.includes('script')) return "Engaging video narrative with scene cues and dialogues.";
  if (t.includes('headlines') || t.includes('headline generator')) return "Catchy, high-conversion headings optimized for click-through rate.";
  if (t.includes('landing page') || t.includes('homepage hero')) return "High-converting web copy to capture attention and drive sales.";
  if (t.includes('product description')) return "Compelling feature-benefit descriptions for e-commerce products.";
  if (t.includes('faq')) return "Helpful answers to common customer queries and search intent.";
  if (t.includes('manifesto') || t.includes('mission') || t.includes('vision')) return "Inspirational messaging defining your brand identity.";
  if (t.includes('case study')) return "Demonstrate real client success with metrics and testimonials.";
  if (t.includes('press release')) return "Official news announcement formatted for journalists and media outlets.";
  if (t.includes('bio')) return "Concise profile summaries that define your brand voice.";
  if (t.includes('repurpose') || t.includes('rewrite')) return "Adapt existing text into a fresh, polished perspective.";
  if (t.includes('sms') || t.includes('notification')) return "Direct, short-form copy with clear calls to action.";
  if (t.includes('onboarding') || t.includes('tooltip')) return "Friendly system microcopy to guide users smoothly.";
  
  // Default clean fallback
  return `Professional copy template for ${title.toLowerCase()}.`;
};
